import type { RunStore } from '../contracts.js';
import { createConvexRunStore } from './convex-run-store.js';
import { createMemoryRunStore } from './testing/memory-run-store.js';

export function createRunStore(env: Record<string, string | undefined>): RunStore {
  const url = env.CONVEX_URL;
  if (!url) {
    console.warn('CONVEX_URL missing, using in-memory run store');
    return createMemoryRunStore();
  }
  return createConvexRunStore(url);
}
